  { name: 'deals', url: 'https://ivx-holdings-platform.onrender.com/api/deals' },
];
const results = [];
let count = 0;
const startTime = Date.now();

async function probe() {
  count++;
  const ts = new Date().toISOString();
  for (const ep of ENDPOINTS) {
    const t0 = Date.now();
    try {
      const res = await fetch(ep.url, { signal: AbortSignal.timeout(15000) });
      const elapsed = Date.now() - t0;
      const ok = res.ok;
      const status = res.status;
      let body = '';
      try { body = await res.text(); } catch {}
      results.push({ n: count, ts, ep: ep.name, status, ok, elapsed, bodyLen: body.length });
      if (!ok) console.log(`[${ts}] FAIL ${ep.name} ${status} ${elapsed}ms`);
    } catch (e) {
      const elapsed = Date.now() - t0;
      results.push({ n: count, ts, ep: ep.name, status: 0, ok: false, elapsed, error: e.message });
      console.log(`[${ts}] ERROR ${ep.name} ${elapsed}ms ${e.message}`);
    }
  }
  if (count % 10 === 0) {
    const elapsed = Date.now() - startTime;
    const success = results.filter(r => r.ok).length;
    const fail = results.filter(r => !r.ok).length;
    const latencies = results.map(r => r.elapsed).sort((a,b) => a-b);
    const p50 = latencies[Math.floor(latencies.length * 0.5)] || 0;
    const p95 = latencies[Math.floor(latencies.length * 0.95)] || 0;
    const p99 = latencies[Math.floor(latencies.length * 0.99)] || 0;
    const max = Math.max(...latencies);
    console.log(`\n=== SOAK PROGRESS ${count} iterations, ${Math.floor(elapsed/1000)}s ===`);
    console.log(`Requests: ${results.length}, Success: ${success}, Fail: ${fail}`);
    console.log(`Latency: p50=${p50}ms p95=${p95}ms p99=${p99}ms max=${max}ms`);
    const healthResults = results.filter(r => r.ep === 'health');
    const shas = new Set(healthResults.map(r => { try { return JSON.parse(r.body || '{}').commit; } catch { return null; } }).filter(Boolean));
    console.log(`Production SHAs seen: ${[...shas].join(', ')}`);
    console.log('');
  }
}

console.log(`SOAK TEST STARTED at ${new Date().toISOString()}`);
console.log(`Probing ${ENDPOINTS.length} endpoints every 30 seconds`);

// Run immediately, then every 30s
