  { name: 'chat', url: 'https://ivx-holdings-platform.onrender.com/api/public/chat', method: 'POST', body: JSON.stringify({ message: 'What is 2+2?' }) },
];
const results = [];
let count = 0;
const startTime = Date.now();

async function probe() {
  count++;
  const ts = new Date().toISOString();
  for (const ep of ENDPOINTS) {
    const t0 = Date.now();
    try {
      const opts = { signal: AbortSignal.timeout(12000), headers: { 'Content-Type': 'application/json' } };
      if (ep.method === 'POST') { opts.method = 'POST'; opts.body = ep.body; }
      const res = await fetch(ep.url, opts);
      const elapsed = Date.now() - t0;
      const ok = res.ok;
      const status = res.status;
      let body = '';
      try { body = await res.text(); } catch {}
      results.push({ n: count, ts, ep: ep.name, status, ok, elapsed, bodyLen: body.length, body });
      if (!ok) console.log(`[${ts}] FAIL ${ep.name} ${status} ${elapsed}ms`);
    } catch (e) {
      const elapsed = Date.now() - t0;
      results.push({ n: count, ts, ep: ep.name, status: 0, ok: false, elapsed, error: e.message });
      console.log(`[${ts}] ERROR ${ep.name} ${elapsed}ms ${e.message}`);
    }
  }
