    console.log(`4xx: ${results.filter(r => r.status >= 400 && r.status < 500).length}, 5xx: ${results.filter(r => r.status >= 500).length}`);
    console.log(`Timeouts: ${results.filter(r => r.error?.includes('timeout') || r.error?.includes('abort')).length}`);
    console.log(`Latency: p50=${p50}ms p95=${p95}ms p99=${p99}ms max=${max}ms`);
    console.log(`Production SHAs: ${[...shas].join(', ')}`);
    console.log(`Health statuses: ${[...statuses].join(', ')}`);
    console.log(`AI provider states: ${[...aiStates].join(', ')}`);
    console.log('');
  }
}

